E = {}

E["arsenal-premier-league-title-2026"] = ("ما الذي يقوله هذا اللقب عن مشروع أرتيتا؟", "<p>مرّ المشروع بثلاث محطات واضحة: بناء هوية تعتمد على الاستحواذ والضغط، ثم الاقتراب من اللقب في مواسم انتهت بالمركز الثاني، ثم تحويل القرب إلى تتويج. وهذا المسار يوضح أن الصبر على المدرب يمنح النادي نتيجة، حين تتوفر سياسة تعاقد منسجمة مع الفكرة التكتيكية.</p><ul><li><strong>الاستمرارية:</strong> بقاء الجهاز الفني سنوات طويلة سمح بتراكم الفكرة.</li><li><strong>الصلابة الدفاعية:</strong> 27 هدفاً في موسم كامل رقم يصنع الألقاب عادة.</li><li><strong>الخبرة من الإخفاقات:</strong> المواسم القريبة من اللقب علّمت اللاعبين إدارة الأسابيع الأخيرة.</li></ul><p>والاختبار القادم هو الحفاظ على المستوى مع ضغط البطولات الأوروبية.</p>")

E["psg-back-to-back-champions-league-2026"] = ("لماذا يصعب الاحتفاظ بلقب دوري الأبطال؟", "<p>قليلة هي الأندية التي دافعت عن اللقب بنجاح في العصر الحديث، لأن البطل يواجه موسماً مرهقاً وخصوماً يدرسونه بدقة، ويفقد أحياناً دوافع لاعبيه بعد بلوغ القمة. ولهذا يعد نجاح باريس مرتين متتاليتين دليلاً على عمق التشكيلة وقدرة المدرب على تدويرها.</p><ul><li><strong>التدوير:</strong> المنافسة على المراكز تبقي اللاعبين في أعلى مستوياتهم.</li><li><strong>إدارة اللياقة:</strong> ضغط الفريق العالي يتطلب راحة ذكية.</li><li><strong>الاستعداد الذهني:</strong> نهائي بودابست حُسم بركلات الترجيح وليس بالأداء.</li></ul><p>وتبقى مباريات الجولات القادمة اختباراً لقدرة الفريق على الإبقاء على الصدارة وصولاً إلى المراكز الثمانية الأولى.</p>")

E["ballon-dor-2026-kane-putellas"] = ("لماذا أثار فوز كين ارتياحاً واسعاً؟", "<p>ارتبط اسم هاري كين طويلاً بسؤال: متى يحصد جائزة كبرى؟ فبعد سنوات من التسجيل الغزير مع توتنهام ثم بايرن ميونخ، جاءت الكرة الذهبية لتكافئ استمراريته. وتحمل الجائزة بعداً رمزياً للكرة الإنجليزية التي لم تحصل عليها منذ عام 2001.</p><ul><li><strong>الاستمرارية:</strong> الجائزة تكافئ موسماً كاملاً وليس مباراة واحدة.</li><li><strong>تعدد الجوائز:</strong> الحفل ضم 13 جائزة بين الرجال والسيدات والأندية والمدربين.</li><li><strong>جيل جديد:</strong> نيل يامال كوبا للمرة الثالثة يعني أن المنافسة القادمة ستكون إسبانية الطابع.</li></ul><p>أما بوتياس فجددت حضورها كواحدة من أهم اللاعبات في تاريخ اللعبة.</p>")

E["spain-world-cup-2026-champions"] = ("دروس تكتيكية من نهائي طويل", "<p>تميز النهائي بسيطرة إسبانية واضحة على الكرة مقابل كتلة دفاعية أرجنتينية متراجعة. وتمثل مثل هذه المباريات اختباراً للصبر، فالفريق المسيطر يحتاج إلى حلول بديلة حين يغلق الخصم المساحات. وكان تغيير توريس وسيلة لكسر الجمود في اللحظة المناسبة.</p><ul><li><strong>الصبر:</strong> استمرار الضغط بلا تهور حتى ظهور الفرصة.</li><li><strong>قوة البدلاء:</strong> هدف الفوز جاء من لاعب نزل من دكة البدلاء.</li><li><strong>الدفاع الجماعي:</strong> هدف واحد في البطولة كلها يعكس تنظيماً استثنائياً.</li></ul><p>ويمكن ربط هذه الصورة بما ناقشناه في مقال دروس مونديال 2026.</p>")

E["afcon-2025-final-morocco-senegal"] = ("كيف تُحسم النزاعات في البطولات القارية؟", "<p>تملك الاتحادات القارية لجان انضباط واستئناف تنظر في الطعون وفق لوائح المسابقة. وفي هذه القضية استندت اللجنة إلى اعتبار الانسحاب خسارة بالقوة، فسجّلت النتيجة 3-0 للمنتخب المقابل. وقد يلجأ الطرف المتضرر عادة إلى هيئات أعلى للتحكيم الرياضي إذا أتاحت اللوائح ذلك.</p><ul><li><strong>اللائحة أولاً:</strong> الانسحاب من المباراة يعاقب غالباً بالخسارة الإدارية.</li><li><strong>حق الطعن:</strong> أشار رئيس الكاف إلى أن السنغال يمكنها الاستئناف.</li><li><strong>متابعة المصادر الرسمية:</strong> قد تتغير الحالة القانونية بعد نشر هذا المقال.</li></ul>")

E["arab-cup-2025-morocco-jordan"] = ("الأردن: قصة نهائي أول", "<p>بلغ الأردن النهائي بعد انتصارين بنتيجة 1-0 على العراق ثم السعودية، وقدم مباراة نهائية قوية قبل أن يخسر في الوقت الإضافي. وهذا المركز الثاني هو الأفضل في تاريخ المنتخب في البطولة، متجاوزاً المركز الرابع عام 1988. وجاء في تغطية المنصات أن اللاعب علوان سجل أربع ركلات جزاء خلال البطولة.</p><ul><li><strong>الانضباط:</strong> فوزان بنتيجة نظيفة في الإقصاء.</li><li><strong>الروح:</strong> قلب التأخر في النهائي أكثر من مرة.</li><li><strong>الطموح:</strong> التأهل إلى كأس العالم 2026 وإلى كأس آسيا 2027 يمنح الجيل زخماً.</li></ul>")

E["asian-cup-2027-saudi-arabia-guide"] = ("ماذا نتوقع من البطولة؟", "<p>تجمع البطولة منتخبات من غرب آسيا وشرقها ووسطها، وتحمل منافسة قوية على اللقب بين اليابان وكوريا الجنوبية وإيران وأستراليا وقطر وأصحاب الأرض. وتتيح المجموعة العربية الأولى مباريات ذات حضور جماهيري كبير في الرياض. وتقام النسخة في فصل الشتاء بعيداً عن حرارة الصيف.</p><ul><li><strong>جدول مكثف:</strong> 51 مباراة في خمسة أسابيع تقريباً.</li><li><strong>طاقة جماهيرية:</strong> قرب الجماهير العربية من الملاعب يرفع الحضور.</li><li><strong>اختبار تنظيمي:</strong> تمثل النسخة تجربة قبل مونديال 2034.</li></ul>")

E["premier-league-2026-27-first-ten-games"] = ("ثلاثة أسئلة تحدد المراحل القادمة", "<p>الأسئلة التي تحكم باقي الموسم تتعلق بمدى استمرارية أرسنال في الحفاظ على الفارق، وقدرة مانشستر سيتي على التكيف بعد غياب غوارديولا، ومصير الأندية الكبيرة المتعثرة في أسفل الجدول. وتبقى مباراة أرسنال وسيتي المقررة في أواخر نوفمبر محطة مهمة.</p><ul><li><strong>هل يتأثر أرسنال بالمنافسة الأوروبية؟</strong> الجدول المزدحم سيختبر عمق التشكيلة.</li><li><strong>هل يستمر برايتون؟</strong> الفرق المفاجئة تتراجع غالباً عند تعاقب الإصابات.</li><li><strong>هل ينجو يونايتد؟</strong> فارق النقاط عن المراكز الأخيرة قليل بعد تسع جولات.</li></ul>")

E["la-liga-2026-27-barcelona-madrid-race"] = ("قراءة في أرقام البداية", "<p>يتفوق برشلونة في فارق الأهداف بوضوح، فقد سجل 46 هدفاً واستقبل 12 في 11 مباراة، أي فارق +34. وفي المقابل لعب ريال مدريد مباراة إضافية، وفارقه +21. وهذه الأرقام تعني أن برشلونة يسيطر هجومياً، بينما يعتمد مدريد على تماسك دفاعي أيضاً بعد أن استقبل 10 أهداف فقط في 12 مباراة.</p><ul><li><strong>الكلاسيكو:</strong> المواجهة المباشرة ستغير ترتيب القمة في أي لحظة.</li><li><strong>أتلتيكو:</strong> يبعد بنقطتين فقط وقد يستغل أي تعثر.</li><li><strong>الإصابات:</strong> عمق التشكيلة يحسم النفس الطويل.</li></ul>")

E["champions-league-2026-27-league-phase-so-far"] = ("كيف تحسب فرصك للتأهل؟", "<p>لا يوجد رصيد ثابت يضمن التأهل المباشر إلى دور الستة عشر، لأن العتبة تتحدد بنتائج المنافسين في آخر جولة. ولذلك لا يتسرع المتابعون بحسم المصير قبل الجولات الأخيرة، حيث تتساوى فرق كثيرة في النقاط ويحسم فارق الأهداف والأهداف المسجلة.</p><ul><li><strong>الجولات الثلاث الأخيرة:</strong> أهم من الأولى لأن الجدول يتضح فيها.</li><li><strong>مباريات المنافسين:</strong> تابع نتائج الفرق القريبة منك في الترتيب.</li><li><strong>الجولة الأخيرة المتزامنة:</strong> تمنع الفرق من حساب النتائج مسبقاً.</li></ul>")

E["como-fabregas-champions-league-debut"] = ("ما الذي يمكن لكومو أن يحققه؟", "<p>الواقعية تقتضي أن يكون الهدف هو المنافسة وتحسين الترتيب، لا الاعتقاد بأن الفريق منافس على اللقب. فالمشاركة الأولى تمنح اللاعبين خبرة لا تقدر بثمن، وتمنح النادي دخلاً ورصيداً جماهيرياً. وسيكون التحدي الأكبر هو الحفاظ على التركيز في مباراتين على صعيد الدوري والبطولة الأوروبية.</p><ul><li><strong>الخبرة:</strong> مواجهة أندية بحجم لايبزيغ ترفع الجاهزية.</li><li><strong>العمق:</strong> سيختبر ازدحام الجدول بدلاء الفريق.</li><li><strong>الصورة:</strong> يتحول النادي إلى اسم معروف أوروبياً.</li></ul>")

E["xg-expected-goals-explained"] = ("مثال تطبيقي بسيط", "<p>تخيل مباراة سدد فيها فريق عشر تسديدات، ثمان منها من خارج المنطقة بقيمة 0.04 لكل منها، واثنتان من داخلها بقيمة 0.3. يكون مجموع xG نحو 0.92، ومعنى ذلك أنه كان يُتوقع هدف واحد تقريباً. فإذا سجل ثلاثة أهداف فنحن أمام كفاءة استثنائية أو حظ، وإذا لم يسجل شيئاً فهو لم يكن بعيداً عن المتوقع.</p><ul><li><strong>الاستخدام الجيد:</strong> مقارنة xG المسجل مع xG المستقبل لمعرفة توازن الفريق.</li><li><strong>الاستخدام السيئ:</strong> الحكم على لاعب من مباراة واحدة.</li><li><strong>التكامل:</strong> اجمع xG مع مشاهدة الفيديو لتفهم سبب الفرص.</li></ul>")

E["pressing-gegenpressing-explained"] = ("تدريبات الضغط في الأكاديميات", "<p>يتدرب الصغار على الضغط من خلال ألعاب مصغرة في مساحات ضيقة، تنتقل فيها الكرة بسرعة بين الفريقين. والهدف تعليمهم أن فقدان الكرة ليس نهاية الهجمة، بل بداية الضغط. ويحتاج المدرب إلى ضبط شدة التمرين حتى لا يرهق الفئات الصغيرة.</p><ul><li><strong>ألعاب المساحات الضيقة:</strong> تزيد عدد اللمسات وسرعة القرار.</li><li><strong>قاعدة الثواني:</strong> بعد فقدان الكرة يضغط الفريق خلال ثوانٍ محدودة.</li><li><strong>التواصل:</strong> الكلام بين اللاعبين يسهّل تحرك الجميع معاً.</li></ul>")

E["penalty-shootout-science"] = ("نصائح للاعب الناشئ", "<p>يستطيع أي لاعب ناشئ تحسين ركلاته بالتكرار مع الضغط. ينصح المدربون بالتدرب بعد جهد بدني حتى تُحاكى حالة المباراة، وبتخصيص مكافآت وعقوبات بسيطة لخلق توتر خفيف. ويساعد روتين التنفس العميق على ضبط الأعصاب قبل الركلة.</p><ul><li><strong>التدرب تحت التعب:</strong> يكشف مدى ثبات التقنية.</li><li><strong>التنويع:</strong> إتقان زاويتين على الأقل.</li><li><strong>الحارس:</strong> الاطلاع على عادات الحارس إن توفرت معلومات.</li></ul>")

E["la-masia-academy-model"] = ("ما الذي يمكن أن يتعلمه الأهل؟", "<p>يلعب الأهل دوراً في تطوير اللاعب الصغير، فالنجاح لا يعتمد على الأكاديمية فقط. يحتاج الطفل إلى بيئة تشجع على التجريب دون خوف من الخطأ، وإلى توازن بين الدراسة والرياضة، وإلى فرص لعب كافية بدل البقاء على مقاعد البدلاء في فرق قوية.</p><ul><li><strong>اللعب كثيراً:</strong> دقائق المباريات أهم من اسم الفريق.</li><li><strong>التنوع:</strong> لعب مراكز مختلفة في الأعمار الصغيرة يطور الفهم.</li><li><strong>الصبر:</strong> كثير من النجوم صعدوا بعد سنوات من التدرج.</li></ul>")

E["football-finances-explained"] = ("كيف تؤثر الأموال على المنافسة؟", "<p>تتيح الإيرادات الكبيرة للأندية دفع أجور أعلى وشراء لاعبين أفضل، لكنها لا تضمن النجاح. فهناك أندية أنفقت كثيراً بلا ألقاب، وأخرى أنجزت الكثير بميزانيات صغيرة بفضل التخطيط. ولهذا تحدث القواعد المالية لتقليص الفجوة قدر المستطاع، لكنها تبقى محل جدل بين من يراها حماية للاستقرار ومن يراها حاجزاً أمام الاستثمار.</p><ul><li><strong>الأجور:</strong> أكبر بند إنفاق لدى معظم الأندية.</li><li><strong>الأكاديمية:</strong> بيع اللاعبين الشباب مصدر ربح مهم.</li><li><strong>الاستدامة:</strong> التوازن بين الإنفاق والإيراد يحمي النادي على المدى الطويل.</li></ul>")

E["fantasy-premier-league-guide"] = ("خطة الجولات الأولى", "<p>في الجولات الأولى ركز على بناء تشكيلة متوازنة وتجنب اللاعبين المصابين أو غير المضمونين في التشكيلة. اختر قائداً يملك فرصاً عالية للمشاركة والتسجيل، ويفضل أن يلعب على أرضه أمام خصم أضعف. وراجع التشكيلة قبل كل جولة في ضوء الإصابات والإيقافات.</p><ul><li><strong>الاستقرار:</strong> لا تغير نصف الفريق كل أسبوع.</li><li><strong>مراقبة الأسعار:</strong> قد ترتفع أسعار اللاعبين الأكثر طلباً.</li><li><strong>خطة الدكة:</strong> اختر بدلاء يشاركون ولو لدقائق.</li></ul>")

E["goalkeeper-evolution-modern-game"] = ("كيف تدرّب حارساً عصرياً؟", "<p>يحتاج الحارس الناشئ إلى تدريب مزدوج: مهارات التصدي التقليدية، وتمارين التمرير تحت الضغط. وتعد الأكاديميات الحديثة اللعب بالقدم جزءاً أساسياً من برنامج الحراس منذ الفئات الصغيرة، وتستخدم تمارين المربعات ليشارك الحارس في اللعب.</p><ul><li><strong>التمركز:</strong> قراءة اللعب أهم من الرشاقة وحدها.</li><li><strong>التمرير:</strong> دقة التمرير القصير والطويل بالقدمين.</li><li><strong>الشخصية:</strong> الحارس قائد صامت يوجه الدفاع.</li></ul>")

E["football-scouting-data-explained"] = ("خطوات عملية لمشجع يريد التحليل", "<p>يمكن لأي مهتم أن يجرب الكشافة بنفسه. اختر لاعباً واحداً وتابع مبارياته خمس مرات، ودوّن ما تراه بعينك، ثم قارن مع الإحصاءات المتاحة. هل تتفق الأرقام مع انطباعك؟ إن اختلفت فاسأل لماذا، وهذه الطريقة تعلمك كيف يعمل الكشافون المحترفون.</p><ul><li><strong>اختر مركزاً واحداً:</strong> المقارنة بين لاعبين في المركز نفسه أدق.</li><li><strong>راقب العمر:</strong> التطور المتوقع يختلف بين ناشئ ولاعب في الثلاثين.</li><li><strong>ابتعد عن مباراة واحدة:</strong> العينة الأكبر أكثر صدقاً.</li></ul>")

E["how-to-read-football-match-tactically"] = ("تمرين بعد المباراة", "<p>بعد انتهاء المباراة اكتب ثلاث ملاحظات: ماذا فعل الفريق الفائز بشكل أفضل؟ أي لحظة غيرت الإيقاع؟ وما التعديل الذي كنت ستجريه لو كنت المدرب؟ هذا التمرين البسيط يحول المشاهدة إلى تعلم، ويجعلك تلاحظ أنماطاً تتكرر في المباريات.</p><ul><li><strong>الاتساق:</strong> كرر التمرين بعد خمس مباريات متتالية.</li><li><strong>المقارنة:</strong> ضع ملاحظاتك بجانب تحليل المدربين.</li><li><strong>المشاركة:</strong> ناقش ملاحظاتك مع أصدقاء يشاهدون المباراة نفسها.</li></ul>")
